// product page route — shared, SEO-critical, price/stock change hourly
export const config = {
  // render once at build for every product
  mode: 'SSG',
  revalidate: false,
};

export async function load({ params }) {
  const product = await db.product(params.sku);          // price + stock
  // personalize the header greeting
  const user = await auth.currentUser();
  return { product, greeting: 'Hi ' + (user?.name ?? '') };
}
